type Shape interface{ isShape() }

type Circle struct{ R float64 }
type Square struct{ Side float64 }

func (Circle) isShape() {}
func (Square) isShape() {}

func Area(s Shape) float64 {
	switch v := s.(type) {
	case Circle:
		return math.Pi * v.R * v.R
	case Square:
		return v.Side * v.Side
	default:
		panic(fmt.Sprintf("unhandled shape %T", v))
	}
}
